import java.util.regex.Pattern;

public class TestTagRemoval2 {
    public static void main(String[] args) {
        String content = "Some note with #test #testa #testb tags";
        String tagText = "#test";

        // Test \b approach (does NOT work with # since # is non-word)
        String escaped1 = Pattern.quote(tagText);
        String pattern1 = "\\b" + escaped1 + "\\b";
        System.out.println("\\b#test\\b matches: " + Pattern.compile(pattern1).matcher(content).find());

        // Test (?<!\w) lookbehind approach (does NOT work either since # is not a word char)
        String pattern2 = "(?<!\\w)" + escaped1 + "\\b";
        System.out.println("(?<!\\w)#test\\b matches: " + Pattern.compile(pattern2).matcher(content).find());

        // The fix: use (?<!\\S) to require a non-whitespace boundary before tag
        // This ensures the tag is a standalone whitespace-delimited token
        String pattern3 = "(?<!\\S)" + escaped1 + "\\b";
        System.out.println("(?<!\\S)#test\\b matches: " + Pattern.compile(pattern3).matcher(content).find());
        String result3 = content.replaceAll(pattern3, "");
        System.out.println("Result with (?<!\\S): '" + result3 + "'");

        // Alternative: split on whitespace and match exact token
        // But simpler: use negative lookbehind for word char
        // The issue is #test should be matched when preceded by whitespace or at start
        // Let's use (?:(?<=\\s)|^) approach
        String pattern4 = "(?:(?<=\\s)|^)" + escaped1 + "\\b";
        System.out.println("\n(?:(?<=\\s)|^)#test\\b matches: " + Pattern.compile(pattern4).matcher(content).find());
        String result4 = content.replaceAll(pattern4, "");
        System.out.println("Result with lookbehind: '" + result4 + "'");

        // Test edge cases
        System.out.println("\n--- Edge case: tag at start of string ---");
        String startContent = "#test some content";
        String startResult4 = startContent.replaceAll(pattern4, "");
        System.out.println("Start: '" + startContent + "' -> '" + startResult4 + "'");

        System.out.println("\n--- Edge case: #testa should not match ---");
        String testaContent = "Has #testa in it";
        String testaResult4 = testaContent.replaceAll(pattern4, "");
        System.out.println("Testa: '" + testaContent + "' -> '" + testaResult4 + "'");

        System.out.println("\n--- Edge case: two #test occurrences ---");
        String doubleContent = "#test and #test again";
        String doubleResult4 = doubleContent.replaceAll(pattern4, "");
        System.out.println("Double: '" + doubleContent + "' -> '" + doubleResult4 + "'");
    }
}
